// ══════════════════════════════════════
// DATA PARSER - parses pasted tab-separated data
// ══════════════════════════════════════
function parseInputData(text, sourceType) {
  // sourceType: "ktb", "agency", "bank", "corp_aa", "corp_a", "fin_aa", "fin_a"
  const lines = text.trim().split(/\r?\n/);
  // Find header row (contains 3M, 6M, etc.)
  let headerIdx = -1;
  for (let i = 0; i < Math.min(lines.length, 5); i++) {
    if (lines[i].includes("3M") || lines[i].includes("1Y")) { headerIdx = i; break; }
  }
  if (headerIdx === -1) return null;

  const headers = lines[headerIdx].split("\t").map(h => h.trim());
  const tenorIdx = {};
  headers.forEach((h, i) => { if (h) tenorIdx[h] = i; });

  const result = {};
  for (let i = headerIdx + 1; i < lines.length; i++) {
    const parts = lines[i].split("\t");
    const date = parts[0]?.trim();
    if (!date || !date.match(/^\d{4}-/)) continue;
    const row = {};
    for (const [tenor, idx] of Object.entries(tenorIdx)) {
      const v = parts[idx]?.trim();
      if (v && !isNaN(parseFloat(v))) row[tenor] = parseFloat(v);
    }
    if (Object.keys(row).length > 0) result[date] = row;
  }
  return result;
}

function mergeData(existing, newParsed, sourceType) {
  const dates = [...existing.dates];
  const series = {};
  for (const [k, v] of Object.entries(existing.series)) {
    series[k] = [...v];
  }

  // Map source type to series keys
  const tenorToSeries = {};
  if (sourceType === "ktb") {
    ["1Y","1.5Y","2Y","2.5Y","3Y","4Y","5Y","7Y","10Y","15Y","20Y","30Y","50Y"].forEach(t => {
      tenorToSeries[t] = "KTB_" + t;
    });
  } else {
    const creditKey = {
      agency: "Agency_AAA", bank: "Bank_AAA",
      corp_aa: "Corp_AA", corp_a: "Corp_A",
      fin_aa: "Fin_AA", fin_a: "Fin_A",
    }[sourceType];
    if (creditKey) tenorToSeries["3Y"] = creditKey + "_3Y";
  }

  // Add new dates and update values
  for (const [date, row] of Object.entries(newParsed)) {
    let dateIdx = dates.indexOf(date);
    if (dateIdx === -1) {
      // Insert in sorted position
      dateIdx = dates.findIndex(d => d > date);
      if (dateIdx === -1) dateIdx = dates.length;
      dates.splice(dateIdx, 0, date);
      for (const k of Object.keys(series)) {
        series[k].splice(dateIdx, 0, null);
      }
    }
    for (const [tenor, seriesKey] of Object.entries(tenorToSeries)) {
      if (row[tenor] !== undefined && series[seriesKey]) {
        series[seriesKey][dateIdx] = row[tenor];
      }
    }
  }

  // Recompute BOK base rate for new dates
  if (series.BOK_Base) {
    const bokChanges = [["2000-01-01",3.25],...BOK_CHANGES];
    series.BOK_Base = dates.map(d => {
      let rate = bokChanges[0][1];
      for (const [cd, cr] of bokChanges) { if (d >= cd) rate = cr; }
      return rate;
    });
  }

  // Recompute spreads
  const ktb3y = series.KTB_3Y;
  const creditPairs = [
    ["Agency_AAA_3Y","Agency_AAA_Spd"], ["Bank_AAA_3Y","Bank_AAA_Spd"],
    ["Corp_AA_3Y","Corp_AA_Spd"], ["Corp_A_3Y","Corp_A_Spd"],
    ["Fin_AA_3Y","Fin_AA_Spd"], ["Fin_A_3Y","Fin_A_Spd"],
  ];
  for (const [yKey, sKey] of creditPairs) {
    if (series[yKey] && ktb3y) {
      series[sKey] = series[yKey].map((v, i) =>
        v != null && ktb3y[i] != null ? Math.round((v - ktb3y[i]) * 1000) / 10 : null
      );
    }
  }

  return { dates, series };
}

// ══════════════════════════════════════
// STORAGE HELPERS
// ══════════════════════════════════════
function loadFromStorage() {
  try {
    if (typeof window === "undefined") return null;
    const d = localStorage.getItem("ra_yield_dates");
    const s = localStorage.getItem("ra_yield_series");
    if (!d || !s) return null;
    return { dates: JSON.parse(d), series: JSON.parse(s) };
  } catch { return null; }
}

function saveToStorage(data) {
  try {
    if (typeof window === "undefined") return;
    localStorage.setItem("ra_yield_dates", JSON.stringify(data.dates));
    localStorage.setItem("ra_yield_series", JSON.stringify(data.series));
  } catch (e) { console.error("Storage save error:", e); }
}

// ══════════════════════════════════════
// CHART COMPONENT
// ══════════════════════════════════════
function YieldChart({ data, selected, axisMap, dateRange, yLeftRange, yRightRange }) {
  const canvasRef = useRef(null);
  const chartRef = useRef(null);

  useEffect(() => {
    if (!canvasRef.current || !data) return;

    (async () => {
    // Load Chart.js from CDN if not already loaded
    if (!window.Chart) {
      await new Promise((resolve, reject) => {
        if (document.querySelector('script[src*="chart.js"]')) {
          const check = setInterval(() => { if (window.Chart) { clearInterval(check); resolve(); } }, 50);
          return;
        }
        const s = document.createElement("script");
        s.src = "https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js";
        s.onload = resolve;
        s.onerror = reject;
        document.head.appendChild(s);
      });
    }
    const ChartJS = window.Chart;
    const ctx = canvasRef.current.getContext("2d");

    if (chartRef.current) chartRef.current.destroy();

    const [startIdx, endIdx] = dateRange;
    const slicedDates = data.dates.slice(startIdx, endIdx + 1);
    const hasLeft = selected.some(id => axisMap[id] === "left");
    const hasRight = selected.some(id => axisMap[id] === "right");
    const leftUnit = selected.find(id => axisMap[id] === "left") ? SERIES_MAP[selected.find(id => axisMap[id] === "left")]?.unit || "%" : "%";
    const rightUnit = selected.find(id => axisMap[id] === "right") ? SERIES_MAP[selected.find(id => axisMap[id] === "right")]?.unit || "bp" : "bp";

    const datasets = selected.map(id => {
      const cfg = SERIES_MAP[id];
      if (!cfg) return null;
      const rawData = (data.series[id] || []).slice(startIdx, endIdx + 1);
      return {
        label: cfg.label,
        data: rawData,
        borderColor: cfg.color,
        backgroundColor: cfg.color + "18",
        borderWidth: cfg.width || 1.5,
        borderDash: cfg.dash || [],
        pointRadius: 0,
        pointHoverRadius: 4,
        tension: 0.1,
        yAxisID: axisMap[id] === "right" ? "yRight" : "yLeft",
        stepped: cfg.stepped ? "before" : false,
        spanGaps: true,
      };
    }).filter(Boolean);

    const scales = {
      x: {
        type: "category",
        ticks: {
          maxTicksLimit: 12,
          font: { size: 10, family: "'Pretendard', sans-serif" },
          color: "#64748b",
          callback: function(val, idx) {
            const d = slicedDates[idx];
            if (!d) return "";
            return d.slice(2, 7).replace("-", "/");
          }
        },
        grid: { color: "#f1f5f9", drawBorder: false },
      },
    };

    if (hasLeft) {
      scales.yLeft = {
        position: "left",
        min: yLeftRange[0], max: yLeftRange[1],
        title: { display: true, text: "(" + leftUnit + ")", font: { size: 11, family: "'Pretendard', sans-serif", weight: "600" }, color: "#0046ff" },
        ticks: { font: { size: 10, family: "'Pretendard', sans-serif" }, color: "#334155",
          callback: v => leftUnit === "bp" ? v.toFixed(0) : v.toFixed(2) },
        grid: { color: "#f1f5f9", drawBorder: false },
      };
    }
    if (hasRight) {
      scales.yRight = {
        position: "right",
        min: yRightRange[0], max: yRightRange[1],
        title: { display: true, text: "(" + rightUnit + ")", font: { size: 11, family: "'Pretendard', sans-serif", weight: "600" }, color: "#64748b" },
        ticks: { font: { size: 10, family: "'Pretendard', sans-serif" }, color: "#64748b",
          callback: v => rightUnit === "bp" ? v.toFixed(0) : v.toFixed(2) },
        grid: { drawOnChartArea: false, drawBorder: false },
      };
    }

    chartRef.current = new ChartJS(ctx, {
      type: "line",
      data: { labels: slicedDates, datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 300 },
        interaction: { mode: "index", intersect: false },
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: "#fff",
            titleColor: "#0f172a",
            bodyColor: "#334155",
            borderColor: "#e2e8f0",
            borderWidth: 1,
            titleFont: { size: 12, family: "'Pretendard', sans-serif", weight: "600" },
            bodyFont: { size: 11, family: "'Pretendard', sans-serif" },
            padding: 10,
            boxPadding: 4,
            callbacks: {
              label: function(ctx) {
                const cfg = SERIES_MAP[selected[ctx.datasetIndex]];
                const unit = cfg?.unit || "%";
                const val = ctx.parsed.y;
                return cfg?.label + ": " + (unit === "bp" ? val?.toFixed(1) + " bp" : val?.toFixed(3) + "%");
              }
            }
          },
        },
        scales,
      },
    });

    })();
    return () => { if (chartRef.current) chartRef.current.destroy(); };
  }, [data, selected, axisMap, dateRange, yLeftRange, yRightRange]);

  return <canvas ref={canvasRef} />;
}

// ══════════════════════════════════════
// RANGE SLIDER COMPONENT
// ══════════════════════════════════════
function RangeSlider({ min, max, value, onChange, labels, height = 40 }) {
  const trackRef = useRef(null);
  const [dragging, setDragging] = useState(null);

  const getPos = useCallback((e) => {
    const rect = trackRef.current.getBoundingClientRect();
    const x = (e.clientX || e.touches?.[0]?.clientX || 0) - rect.left;
    return Math.round(min + (x / rect.width) * (max - min));
  }, [min, max]);

  const handleDown = useCallback((e, handle) => {
    e.preventDefault();
    setDragging(handle);
  }, []);

  useEffect(() => {
    if (dragging === null) return;
    const handleMove = (e) => {
      const pos = getPos(e);
      const clamped = Math.max(min, Math.min(max, pos));
      if (dragging === "left") onChange([Math.min(clamped, value[1] - 1), value[1]]);
      else onChange([value[0], Math.max(clamped, value[0] + 1)]);
    };
    const handleUp = () => setDragging(null);
    window.addEventListener("mousemove", handleMove);
    window.addEventListener("mouseup", handleUp);
    window.addEventListener("touchmove", handleMove);
    window.addEventListener("touchend", handleUp);
    return () => {
      window.removeEventListener("mousemove", handleMove);
      window.removeEventListener("mouseup", handleUp);
      window.removeEventListener("touchmove", handleMove);
      window.removeEventListener("touchend", handleUp);
    };
  }, [dragging, value, min, max, getPos, onChange]);

  const leftPct = ((value[0] - min) / (max - min)) * 100;
  const rightPct = ((value[1] - min) / (max - min)) * 100;

  return (
    <div style={{ position: "relative", height, userSelect: "none", padding: "8px 0" }}>
      <div ref={trackRef} style={{
        position: "relative", height: 6, background: "#e2e8f0", borderRadius: 3, cursor: "pointer"
      }}>
        <div style={{
          position: "absolute", left: leftPct + "%", width: (rightPct - leftPct) + "%",
          height: "100%", background: "#0046ff", borderRadius: 3, opacity: 0.3,
        }} />
        {["left", "right"].map((h, i) => {
          const pct = i === 0 ? leftPct : rightPct;
          return (
            <div key={h}
              onMouseDown={e => handleDown(e, h)}
              onTouchStart={e => handleDown(e, h)}
              style={{
                position: "absolute", left: `calc(${pct}% - 8px)`, top: -5,
                width: 16, height: 16, borderRadius: 8,
                background: "#fff", border: "2px solid #0046ff",
                cursor: "ew-resize", zIndex: 2,
                boxShadow: "0 1px 3px rgba(0,0,0,0.15)",
              }}
            />
          );
        })}
      </div>
      {labels && (
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 4, fontSize: 10, color: "#94a3b8" }}>
          <span>{labels[0]}</span><span>{labels[1]}</span>
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════
// CUSTOM LEGEND
// ══════════════════════════════════════
function CustomLegend({ selected, axisMap }) {
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 14px", padding: "8px 0" }}>
      {selected.map(id => {
        const cfg = SERIES_MAP[id];
        if (!cfg) return null;
        const side = axisMap[id] === "right" ? "R" : "L";
        return (
          <div key={id} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 11 }}>
            <span style={{
              display: "inline-block", width: 18, height: cfg.dash ? 0 : 3,
              borderTop: cfg.dash ? `2px dashed ${cfg.color}` : "none",
              background: cfg.dash ? "none" : cfg.color, borderRadius: 2,
            }} />
            <span style={{ color: "#334155" }}>{cfg.label}</span>
            <span style={{ fontSize: 9, color: "#94a3b8", background: "#f1f5f9", padding: "0 3px", borderRadius: 2 }}>{side}</span>
          </div>
        );
      })}
    </div>
  );
}

// ══════════════════════════════════════
// MAIN APP
// ══════════════════════════════════════
export default function YieldDashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(["BOK_Base", "KTB_3Y", "KTB_10Y"]);
  const [axisMap, setAxisMap] = useState({});
  const [dateRange, setDateRange] = useState([0, 0]);
  const [yLeftRange, setYLeftRange] = useState([1.5, 5.5]);
  const [yRightRange, setYRightRange] = useState([0, 200]);
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState("");
  const [importType, setImportType] = useState("ktb");
  const [importMsg, setImportMsg] = useState("");
  const [showControls, setShowControls] = useState(true);
  const [yLeftAuto, setYLeftAuto] = useState(true);
  const [yRightAuto, setYRightAuto] = useState(true);

  // Initialize data
  useEffect(() => {
    let stored = loadFromStorage();
    if (!stored || !stored.dates || stored.dates.length === 0) {
      stored = { dates: INIT_DATES, series: INIT_SERIES };
      saveToStorage(stored);
    }
    setData(stored);
    setDateRange([Math.max(0, stored.dates.length - 250), stored.dates.length - 1]);
    setLoading(false);
  }, []);

  // Default axis assignment: % -> left, bp -> right
  useEffect(() => {
    const map = {};
    selected.forEach(id => {
      const cfg = SERIES_MAP[id];
      if (!map[id]) map[id] = cfg?.unit === "bp" ? "right" : "left";
    });
    setAxisMap(prev => ({ ...prev, ...Object.fromEntries(selected.filter(id => !prev[id]).map(id => [id, map[id]])) }));
  }, [selected]);

  // Auto y-axis range
  useEffect(() => {
    if (!data) return;
    const [si, ei] = dateRange;
    const leftIds = selected.filter(id => axisMap[id] !== "right");
    const rightIds = selected.filter(id => axisMap[id] === "right");

    if (yLeftAuto && leftIds.length > 0) {
      let min = Infinity, max = -Infinity;
      leftIds.forEach(id => {
        const vals = (data.series[id] || []).slice(si, ei + 1).filter(v => v != null);
        vals.forEach(v => { if (v < min) min = v; if (v > max) max = v; });
      });
      if (min !== Infinity) {
        const pad = (max - min) * 0.08 || 0.2;
        setYLeftRange([Math.floor((min - pad) * 20) / 20, Math.ceil((max + pad) * 20) / 20]);
      }
    }
    if (yRightAuto && rightIds.length > 0) {
      let min = Infinity, max = -Infinity;
      rightIds.forEach(id => {
        const vals = (data.series[id] || []).slice(si, ei + 1).filter(v => v != null);
        vals.forEach(v => { if (v < min) min = v; if (v > max) max = v; });
      });
      if (min !== Infinity) {
        const pad = (max - min) * 0.08 || 10;
        setYRightRange([Math.floor(min - pad), Math.ceil(max + pad)]);
      }
    }
  }, [data, selected, axisMap, dateRange, yLeftAuto, yRightAuto]);

  const toggleSeries = (id) => {
    setSelected(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const toggleAxis = (id) => {
    setAxisMap(prev => ({ ...prev, [id]: prev[id] === "right" ? "left" : "right" }));
  };

  const handleImport = async () => {
    if (!importText.trim()) return;
    const parsed = parseInputData(importText, importType);
    if (!parsed || Object.keys(parsed).length === 0) {
      setImportMsg("❌ 파싱 실패: 데이터 형식을 확인하세요");
      return;
    }
    const merged = mergeData(data, parsed, importType);
    setData(merged);
    saveToStorage(merged);
    setDateRange([Math.max(0, merged.dates.length - 250), merged.dates.length - 1]);
    setImportMsg("✅ " + Object.keys(parsed).length + "일 데이터 업데이트 완료");
    setImportText("");
    setTimeout(() => setImportMsg(""), 3000);
  };

  const handleReset = async () => {
    const fresh = { dates: INIT_DATES, series: INIT_SERIES };
    setData(fresh);
    saveToStorage(fresh);
    setDateRange([Math.max(0, fresh.dates.length - 250), fresh.dates.length - 1]);
  };

  const groups = [
    { key: "base", title: "기준금리", items: ALL_SERIES.filter(s => s.group === "base") },
    { key: "ktb", title: "국고채", items: ALL_SERIES.filter(s => s.group === "ktb") },
    { key: "credit", title: "크레딧 3년", items: ALL_SERIES.filter(s => s.group === "credit") },
    { key: "spread", title: "스프레드 (vs 국고3년)", items: ALL_SERIES.filter(s => s.group === "spread") },
  ];

  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100vh", background: "#fff", fontFamily: "'Pretendard', sans-serif" }}>
        <div style={{ textAlign: "center", color: "#64748b" }}>
          <div style={{ fontSize: 28, marginBottom: 8 }}>📊</div>
          <div style={{ fontSize: 13 }}>금리 데이터 로딩 중...</div>
        </div>
      </div>
    );
  }

  const dateLabels = data ? [data.dates[dateRange[0]] || "", data.dates[dateRange[1]] || ""] : ["", ""];

  return (
    <div style={{ display: "flex", height: "100vh", background: "#fff", fontFamily: "'Pretendard', -apple-system, BlinkMacSystemFont, sans-serif", color: "#0f172a", overflow: "hidden" }}>
      {/* LEFT PANEL - Controls */}
      <div style={{
        width: showControls ? 260 : 0, minWidth: showControls ? 260 : 0,
        borderRight: showControls ? "1px solid #e2e8f0" : "none",
        overflow: "hidden", transition: "all 0.2s", display: "flex", flexDirection: "column",
      }}>
        <div style={{ padding: "14px 16px 8px", borderBottom: "1px solid #e2e8f0" }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#0046ff", letterSpacing: -0.3 }}>📊 금리 차트</div>
          <div style={{ fontSize: 10, color: "#94a3b8", marginTop: 2 }}>시리즈 선택 · 축 배정</div>
        </div>

        <div style={{ flex: 1, overflow: "auto", padding: "8px 12px" }}>
          {groups.map(g => (
            <div key={g.key} style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 10, fontWeight: 700, color: "#0046ff", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4, padding: "4px 0", borderBottom: "1px solid #f1f5f9" }}>
                {g.title}
              </div>
              {g.items.map(s => {
                const isSelected = selected.includes(s.id);
                const axis = axisMap[s.id] || "left";
                return (
                  <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 4, padding: "3px 0", fontSize: 11 }}>
                    <input type="checkbox" checked={isSelected} onChange={() => toggleSeries(s.id)}
                      style={{ accentColor: s.color, width: 13, height: 13, cursor: "pointer" }} />
                    <span style={{
                      width: 10, height: 10, borderRadius: 2,
                      background: s.dash ? "none" : s.color,
                      border: s.dash ? `2px dashed ${s.color}` : "none",
                      flexShrink: 0,
                    }} />
                    <span style={{ flex: 1, color: isSelected ? "#0f172a" : "#94a3b8", cursor: "pointer", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}
                      onClick={() => toggleSeries(s.id)}>
                      {s.label}
                    </span>
                    {isSelected && (
                      <button onClick={() => toggleAxis(s.id)} style={{
                        fontSize: 9, padding: "1px 4px", borderRadius: 3, cursor: "pointer",
                        background: axis === "right" ? "#f1f5f9" : "#0046ff10",
                        color: axis === "right" ? "#64748b" : "#0046ff",
                        border: `1px solid ${axis === "right" ? "#e2e8f0" : "#0046ff30"}`,
                        fontWeight: 600,
                      }}>
                        {axis === "right" ? "R" : "L"}
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          ))}

          {/* Y-axis range controls */}
          <div style={{ marginTop: 8, padding: "8px 0", borderTop: "1px solid #f1f5f9" }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: "#0046ff", marginBottom: 6 }}>Y축 범위</div>
            {["left", "right"].map(side => {
              const range = side === "left" ? yLeftRange : yRightRange;
              const setRange = side === "left" ? setYLeftRange : setYRightRange;
              const auto = side === "left" ? yLeftAuto : yRightAuto;
              const setAuto = side === "left" ? setYLeftAuto : setYRightAuto;
              const hasSeries = selected.some(id => (axisMap[id] || "left") === side);
              if (!hasSeries) return null;
              return (
                <div key={side} style={{ marginBottom: 6 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 3 }}>
                    <span style={{ fontSize: 10, color: "#64748b", fontWeight: 600 }}>{side === "left" ? "좌축" : "우축"}</span>
                    <label style={{ display: "flex", alignItems: "center", gap: 2, fontSize: 9, color: "#94a3b8", cursor: "pointer" }}>
                      <input type="checkbox" checked={auto} onChange={() => setAuto(!auto)} style={{ width: 10, height: 10 }} /> auto
                    </label>
                  </div>
                  {!auto && (
                    <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
                      <input type="number" value={range[0]} step={side === "right" ? 10 : 0.1}
                        onChange={e => setRange([parseFloat(e.target.value) || 0, range[1]])}
                        style={{ width: 52, padding: "2px 4px", fontSize: 10, border: "1px solid #e2e8f0", borderRadius: 4, textAlign: "center" }} />
                      <span style={{ fontSize: 9, color: "#94a3b8" }}>~</span>
                      <input type="number" value={range[1]} step={side === "right" ? 10 : 0.1}
                        onChange={e => setRange([range[0], parseFloat(e.target.value) || 0])}
                        style={{ width: 52, padding: "2px 4px", fontSize: 10, border: "1px solid #e2e8f0", borderRadius: 4, textAlign: "center" }} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Bottom buttons */}
        <div style={{ padding: "8px 12px", borderTop: "1px solid #e2e8f0", display: "flex", gap: 6 }}>
          <button onClick={() => setShowImport(!showImport)} style={{
            flex: 1, padding: "6px", borderRadius: 6, border: "1px solid #0046ff30", background: showImport ? "#0046ff10" : "#fff",
            color: "#0046ff", fontSize: 10, fontWeight: 600, cursor: "pointer",
          }}>📥 데이터 입력</button>
          <button onClick={handleReset} style={{
            padding: "6px 10px", borderRadius: 6, border: "1px solid #e2e8f0", background: "#fff",
            color: "#94a3b8", fontSize: 10, cursor: "pointer",
          }}>초기화</button>
        </div>
      </div>

      {/* MAIN AREA */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
        {/* Toggle sidebar button */}
        <div style={{ display: "flex", alignItems: "center", padding: "6px 16px", borderBottom: "1px solid #f1f5f9", gap: 8 }}>
          <a href="/" style={{ fontSize: 11, color: "#94a3b8", textDecoration: "none", marginRight: 8 }}>← 컨트롤타워</a>
          <button onClick={() => setShowControls(!showControls)} style={{
            padding: "3px 8px", borderRadius: 4, border: "1px solid #e2e8f0", background: "#fff",
            color: "#64748b", fontSize: 11, cursor: "pointer",
          }}>{showControls ? "◀" : "▶ 설정"}</button>
          <span style={{ fontSize: 12, fontWeight: 600, color: "#0f172a" }}>
            {dateLabels[0]} ~ {dateLabels[1]}
          </span>
          <span style={{ fontSize: 10, color: "#94a3b8", marginLeft: "auto" }}>
            {data?.dates?.length || 0}일 데이터
          </span>
        </div>

        {/* Chart */}
        <div style={{ flex: 1, padding: "8px 16px 0", position: "relative", minHeight: 0 }}>
          <CustomLegend selected={selected} axisMap={axisMap} />
          <div style={{ height: "calc(100% - 40px)", position: "relative" }}>
            <YieldChart
              data={data} selected={selected} axisMap={axisMap}
              dateRange={dateRange} yLeftRange={yLeftRange} yRightRange={yRightRange}
            />
          </div>
        </div>

        {/* Date Range Slider */}
        <div style={{ padding: "4px 20px 12px" }}>
          <div style={{ fontSize: 10, color: "#94a3b8", marginBottom: 2 }}>기간 조절 (드래그)</div>
          <RangeSlider
            min={0} max={(data?.dates?.length || 1) - 1}
            value={dateRange} onChange={setDateRange}
            labels={data ? [data.dates[0], data.dates[data.dates.length - 1]] : undefined}
          />
          {/* Quick range buttons */}
          <div style={{ display: "flex", gap: 4, marginTop: 4 }}>
            {[
              { label: "3M", days: 65 }, { label: "6M", days: 130 },
              { label: "1Y", days: 260 }, { label: "2Y", days: 520 },
              { label: "전체", days: 99999 },
            ].map(r => (
              <button key={r.label} onClick={() => {
                const end = (data?.dates?.length || 1) - 1;
                setDateRange([Math.max(0, end - r.days), end]);
              }} style={{
                padding: "2px 8px", borderRadius: 4, border: "1px solid #e2e8f0",
                background: "#fff", color: "#64748b", fontSize: 10, cursor: "pointer",
              }}>{r.label}</button>
            ))}
          </div>
        </div>

        {/* Import Panel */}
        {showImport && (
          <div style={{ borderTop: "1px solid #e2e8f0", padding: "12px 16px", maxHeight: 220, overflow: "auto" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <span style={{ fontSize: 11, fontWeight: 600, color: "#0f172a" }}>데이터 입력</span>
              <select value={importType} onChange={e => setImportType(e.target.value)} style={{
                padding: "3px 6px", borderRadius: 4, border: "1px solid #e2e8f0", fontSize: 10,
                color: "#334155", background: "#fff",
              }}>
                <option value="ktb">국고채</option>
                <option value="agency">특수채AAA</option>
                <option value="bank">은행채AAA</option>
                <option value="corp_aa">회사채AA-</option>
                <option value="corp_a">회사채A+</option>
                <option value="fin_aa">기타금융채AA-</option>
                <option value="fin_a">기타금융채A+</option>
              </select>
              <button onClick={handleImport} style={{
                padding: "4px 12px", borderRadius: 6, border: "none", background: "#0046ff",
                color: "#fff", fontSize: 10, fontWeight: 600, cursor: "pointer",
              }}>업데이트</button>
            </div>
            <textarea value={importText} onChange={e => setImportText(e.target.value)}
              placeholder={"기존 데이터와 동일한 형식으로 붙여넣기\n(날짜\t3M\t6M\t...\t50Y 형식)"}
              style={{
                width: "100%", height: 120, padding: 8, borderRadius: 6, border: "1px solid #e2e8f0",
                fontSize: 10, fontFamily: "monospace", color: "#334155", background: "#f8fafc",
                resize: "vertical",
              }} />
            {importMsg && <div style={{ fontSize: 11, color: importMsg.startsWith("✅") ? "#16a34a" : "#dc2626", marginTop: 4 }}>{importMsg}</div>}
            <div style={{ fontSize: 9, color: "#94a3b8", marginTop: 4 }}>
              * 데이터 소스에서 복사 → 위 칸에 붙여넣기 → 소스 타입 선택 → 업데이트. 기존 데이터에 새 날짜가 추가/업데이트됩니다.
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
